  1→import Phaser from 'phaser';
  2→import { Difficulty, GameMode, DIFFICULTIES, type DifficultyConfig } from '../types/GameMode';
  3→import { isChristmasSeason } from '../utils/seasonChecker';
  4→import { getSafeSelectedWallpaper, getWallpaperDef } from '../utils/wallpaper';
  5→
  6→interface ButtonCardConfig {
  7→  color: number;
  8→  strokeColor?: number;
  9→  emoji: string;
 10→  title: string;
 11→  description: string;
 12→  info1: string;
 13→  info2: string;
 14→  onPointerDown: () => void;
 15→}
 16→
 17→export default class DifficultySelectScene extends Phaser.Scene {
 18→  private gameMode: GameMode = GameMode.CLASSIC;
 19→
 20→  constructor() {
 21→    super('DifficultySelectScene');
 22→  }
 23→
 24→  init(data: { gameMode?: GameMode }) {
 25→    if (data.gameMode) {
 26→      this.gameMode = data.gameMode;
 27→    }
 28→  }
 29→
 30→  preload() {
 31→    // 선택된 배경화면 미리 로딩 (GameScene 진입 전 캐싱)
 32→    const wpId = getSafeSelectedWallpaper();
 33→    const wpDef = wpId ? getWallpaperDef(wpId) : null;
 34→    if (wpDef && !this.textures.exists(wpDef.bgKey)) {
 35→      this.load.image(wpDef.bgKey, wpDef.bgPath);
 36→    }
 37→
 38→    // 난이도 선택 화면 배경
 39→    if (!this.textures.exists('background')) {
 40→      this.load.image('background', 'assets/backgrounds/background.webp');
 41→    }
 42→
 43→    // ── 게임 에셋 미리 로딩 (캐시된 항목은 건너뜀) ──
 44→    if (this.gameMode === GameMode.CLASSIC) {
 45→      // 배경 (모든 난이도)
 46→      if (!this.textures.exists('background2')) this.load.image('background2', 'assets/backgrounds/background2.webp');
 47→      if (!this.textures.exists('background3')) this.load.image('background3', 'assets/backgrounds/background3.webp');
 48→      if (isChristmasSeason() && !this.textures.exists('xmas_background')) {
 49→        this.load.image('xmas_background', 'assets/backgrounds/xmas_background.webp');
 50→      }
 51→
 52→      // 플레이어
 53→      if (!this.textures.exists('front')) this.load.image('front', 'assets/players/chibi_front.webp');
 54→      if (!this.textures.exists('left')) this.load.image('left', 'assets/players/chibi_left.webp');
 55→      if (!this.textures.exists('right')) this.load.image('right', 'assets/players/chibi_right.webp');
 56→
 57→      // 똥 이미지
 58→      if (!this.textures.exists('poop')) this.load.image('poop', 'assets/poops/poop.webp');
 59→      if (!this.textures.exists('poop_glasses')) this.load.image('poop_glasses', 'assets/poops/poop_glasses.webp');
 60→      if (!this.textures.exists('poop_sunglass')) this.load.image('poop_sunglass', 'assets/poops/poop_sunglass.webp');
 61→      if (!this.textures.exists('poop_sunglass2')) this.load.image('poop_sunglass2', 'assets/poops/poop_sunglass2.webp');
 62→      if (!this.textures.exists('poop_smile')) this.load.image('poop_smile', 'assets/poops/poop_smile.webp');
 63→      if (!this.textures.exists('gold_poop')) this.load.image('gold_poop', 'assets/poops/gold_poop.webp');
 64→      if (!this.textures.exists('diamond_poop')) this.load.image('diamond_poop', 'assets/poops/diamond_poop.webp');
 65→      if (!this.textures.exists('topaz_poop')) this.load.image('topaz_poop', 'assets/poops/topaz.webp');
 66→
 67→      // 크리스마스 시즌 똥
 68→      if (isChristmasSeason()) {
 69→        if (!this.textures.exists('xmas_poop_ribbon')) this.load.image('xmas_poop_ribbon', 'assets/poops/xmas_present_poop.webp');
 70→        if (!this.textures.exists('xmas_poop_nose')) this.load.image('xmas_poop_nose', 'assets/poops/xmas_nose_poop.webp');
 71→        if (!this.textures.exists('xmas_poop_santa')) this.load.image('xmas_poop_santa', 'assets/poops/xmas_santa_poop.webp');
 72→        if (!this.textures.exists('xmas_poop_rudolf')) this.load.image('xmas_poop_rudolf', 'assets/poops/xmas_rudolf_poop.webp');
 73→        if (!this.textures.exists('xmas_poop_beard')) this.load.image('xmas_poop_beard', 'assets/poops/xmas_beard_poop.webp');
 74→      }
 75→
 76→      // BGM
 77→      if (!this.cache.audio.exists('bgMusic')) this.load.audio('bgMusic', 'assets/bgms/poop.mp3');
 78→      if (isChristmasSeason() && !this.cache.audio.exists('xmasBgMusic')) this.load.audio('xmasBgMusic', 'assets/bgms/xmas_poop.mp3');
 79→
 80→    }
 81→  }
 82→
 83→  create() {
 84→    // 배경 이미지 추가
 85→    const background = this.add.image(200, 300, 'background');
 86→    background.setDisplaySize(400, 600);
 87→
 88→    // 반투명 오버레이로 가독성 향상
 89→    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.4);
 90→
 91→    // 타이틀 배경
 92→    this.add.rectangle(200, 75, 350, 72, 0x000000, 0.7)
 93→      .setStrokeStyle(3, 0xFFD700);
 94→
 95→    // 타이틀
 96→    this.add.text(200, 60, '🎮 난이도 선택 🎮', {
 97→      fontSize: '26px',
 98→      color: '#FFD700',
 99→      fontStyle: 'bold',
100→      stroke: '#000',
101→      strokeThickness: 5,
102→      padding: { top: 4 }
103→    }).setOrigin(0.5);
104→
105→    this.add.text(200, 92, '도전할 난이도를 선택하세요', {
106→      fontSize: '13px',
107→      color: '#ffffff',
108→      stroke: '#000',
109→      strokeThickness: 3
110→    }).setOrigin(0.5);
111→
112→    // 2x2 그리드로 버튼 배치
113→    const startX = 100;
114→    const startY = 210;
115→    const spacingX = 200;
116→    const spacingY = 180;
117→
118→    DIFFICULTIES.forEach((difficultyConfig: DifficultyConfig, index: number) => {
119→      const col = index % 2;
120→      const row = Math.floor(index / 2);
121→      const x = startX + (col * spacingX);
122→      const y = startY + (row * spacingY);
123→
124→      this.createDifficultyButton(difficultyConfig, x, y);
125→    });
126→
127→    // 4번째 셀 (col=1, row=1): PHYSICAL 버튼
128→    this.createPureButton(startX + spacingX, startY + spacingY);
129→
130→    // 뒤로가기 버튼
131→    const backButtonBg = this.add.rectangle(200, 560, 150, 40, 0xffffff, 1);
132→    backButtonBg.setStrokeStyle(3, 0x000000);
133→
134→    const backButton = this.add.text(200, 560, '← 뒤로가기', {
135→      fontSize: '18px',
136→      color: '#000',
137→      fontStyle: 'bold'
138→    }).setOrigin(0.5);
139→
140→    // 씬 전환 직후 포인터 상태 전파 방지
141→    this.time.delayedCall(200, () => {
142→      backButtonBg.setInteractive({ useHandCursor: true });
143→      backButton.setInteractive({ useHandCursor: true });
144→
145→      const backElements = [backButtonBg, backButton];
146→      backElements.forEach(element => {
147→        element.on('pointerover', () => {
148→          backButtonBg.setFillStyle(0xffff99);
149→          backButton.setScale(1.05);
150→        });
151→
152→        element.on('pointerout', () => {
153→          backButtonBg.setFillStyle(0xffffff);
154→          backButton.setScale(1);
155→        });
156→
157→        element.on('pointerdown', () => {
158→          this.scene.start('ModeSelectScene');
159→        });
160→      });
161→    });
162→  }
163→
164→  private createDifficultyButton(difficultyConfig: DifficultyConfig, x: number, y: number) {
165→    this.createButtonCard(x, y, {
166→      color: difficultyConfig.color,
167→      emoji: this.getDifficultyEmoji(difficultyConfig.difficulty),
168→      title: difficultyConfig.name,
169→      description: difficultyConfig.description,
170→      info1: `💩 ${difficultyConfig.poopCount}개`,
171→      info2: `⚡ ${this.getSpeedText(difficultyConfig.baseSpeed)}`,
172→      onPointerDown: () => this.startGame(difficultyConfig.difficulty)
173→    });
174→  }
175→
176→  private createPureButton(x: number, y: number) {
177→    this.createButtonCard(x, y, {
178→      color: 0xeeeeee,
179→      strokeColor: 0x888888,
180→      emoji: '⚡',
181→      title: 'PHYSICAL',
182→      description: '능력 없음 · 순수 실력',
183→      info1: '🚫 캐릭터 능력 비활성',
184→      info2: '📊 EXTREME 기준 난이도',
185→      onPointerDown: () => this.scene.start('GameScene', {
186→        gameMode: this.gameMode,
187→        difficulty: Difficulty.EXTREME,
188→        purePhysical: true
189→      })
190→    });
191→  }
192→
193→  private createButtonCard(x: number, y: number, config: ButtonCardConfig) {
194→    const { color, strokeColor = 0x000000 } = config;
195→
196→    const shadow = this.add.rectangle(x + 4, y + 4, 170, 165, 0x000000, 0.4);
197→
198→    const button = this.add.rectangle(x, y, 170, 165, color, 1);
199→    button.setStrokeStyle(3, strokeColor);
200→
201→    // 이모지: 카드 상단에서 충분한 여백 확보 (카드 상단 y-82, 이모지 중심 y-44)
202→    const emojiText = this.add.text(x, y - 44, config.emoji, {
203→      fontSize: '34px',
204→      padding: { top: 6 }
205→    }).setOrigin(0.5);
206→
207→    const title = this.add.text(x, y - 10, config.title, {
208→      fontSize: '20px',
209→      color: '#000',
210→      fontStyle: 'bold',
211→      stroke: '#fff',
212→      strokeThickness: 2
213→    }).setOrigin(0.5);
214→
215→    const description = this.add.text(x, y + 14, config.description, {
216→      fontSize: '11px',
217→      color: '#333',
218→      align: 'center'
219→    }).setOrigin(0.5);
220→
221→    const infoBg = this.add.rectangle(x, y + 47, 154, 40, 0x000000, 0.15)
222→      .setStrokeStyle(1, 0x000000, 0.2);
223→
224→    const info1 = this.add.text(x, y + 38, config.info1, {
225→      fontSize: '11px',
226→      color: '#111',
227→      fontStyle: 'bold'
228→    }).setOrigin(0.5);
229→
230→    const info2 = this.add.text(x, y + 55, config.info2, {
231→      fontSize: '11px',
232→      color: '#111',
233→      fontStyle: 'bold'
234→    }).setOrigin(0.5);
235→
236→    // 씬 전환 직후 포인터 상태 전파 방지
237→    this.time.delayedCall(200, () => {
238→      button.setInteractive({ useHandCursor: true });
239→      const elements = [button, emojiText, title, description, infoBg, info1, info2];
240→
241→      elements.forEach(element => {
242→        if (element !== button) {
243→          element.setInteractive({ useHandCursor: true });
244→        }
245→
246→        element.on('pointerover', () => {
247→          button.setFillStyle(this.lightenColor(color));
248→          button.setScale(1.06);
249→          shadow.setScale(1.06);
250→          emojiText.setScale(1.15);
251→          title.setScale(1.05);
252→          description.setScale(1.05);
253→          infoBg.setScale(1.06);
254→          info1.setScale(1.05);
255→          info2.setScale(1.05);
256→        });
257→
258→        element.on('pointerout', () => {
259→          button.setFillStyle(color);
260→          button.setScale(1);
261→          shadow.setScale(1);
262→          emojiText.setScale(1);
263→          title.setScale(1);
264→          description.setScale(1);
265→          infoBg.setScale(1);
266→          info1.setScale(1);
267→          info2.setScale(1);
268→        });
269→
270→        element.on('pointerdown', () => {
271→          config.onPointerDown();
272→        });
273→      });
274→    });
275→  }
276→
277→  private getDifficultyEmoji(difficulty: string): string {
278→    switch (difficulty) {
279→      case 'normal': return '😐';
280→      case 'hard': return '😰';
281→      case 'extreme': return '💀';
282→      default: return '🎮';
283→    }
284→  }
285→
286→  private getSpeedText(baseSpeed: number): string {
287→    if (baseSpeed <= 150) return '느림';
288→    if (baseSpeed <= 175) return '보통';
289→    if (baseSpeed <= 200) return '빠름';
290→    return '매우 빠름';
291→  }
292→
293→  private lightenColor(color: number): number {
294→    const r = Math.min(255, ((color >> 16) & 0xFF) + 30);
295→    const g = Math.min(255, ((color >> 8) & 0xFF) + 30);
296→    const b = Math.min(255, (color & 0xFF) + 30);
297→    return (r << 16) | (g << 8) | b;
298→  }
299→
300→  private startGame(difficulty: Difficulty) {
301→    this.scene.start('GameScene', {
302→      gameMode: this.gameMode,
303→      difficulty: difficulty
304→    });
305→  }
306→}
