  1→import Phaser from 'phaser';
  2→import { RELEASE_NOTES } from '../data/releaseNotes';
  3→
  4→export default class ReleaseNotesScene extends Phaser.Scene {
  5→  private scrollContainer!: Phaser.GameObjects.Container;
  6→  private maskShape!: Phaser.GameObjects.Graphics;
  7→  private scrollY: number = 0;
  8→  private maxScrollY: number = 0;
  9→  private isDragging: boolean = false;
 10→  private dragStartY: number = 0;
 11→  private dragStartScrollY: number = 0;
 12→
 13→  constructor() {
 14→    super('ReleaseNotesScene');
 15→  }
 16→
 17→  preload() {
 18→    if (!this.textures.exists('background2')) {
 19→      this.load.image('background2', 'assets/backgrounds/background2.webp');
 20→    }
 21→  }
 22→
 23→  create() {
 24→    this.scrollY = 0;
 25→
 26→    // 배경
 27→    const background = this.add.image(200, 300, 'background2');
 28→    background.setDisplaySize(400, 600);
 29→
 30→    // 반투명 오버레이 (더 어둡게)
 31→    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.7);
 32→
 33→    // 타이틀 (고정)
 34→    this.add.text(200, 35, '릴리즈 노트', {
 35→      fontSize: '26px',
 36→      color: '#fff',
 37→      fontStyle: 'bold',
 38→      stroke: '#000',
 39→      strokeThickness: 5,
 40→    }).setOrigin(0.5).setDepth(10);
 41→
 42→    // 스크롤 영역 마스크
 43→    this.maskShape = this.make.graphics({ x: 0, y: 0 });
 44→    this.maskShape.fillRect(0, 70, 400, 470);
 45→    const mask = this.maskShape.createGeometryMask();
 46→    this.events.once('shutdown', () => { this.maskShape.destroy(); });
 47→
 48→    // 스크롤 컨테이너
 49→    this.scrollContainer = this.add.container(0, 70);
 50→    this.scrollContainer.setMask(mask);
 51→
 52→    // 릴리즈 노트 내용 생성
 53→    let currentY = 10;
 54→
 55→    RELEASE_NOTES.forEach((release, index) => {
 56→      const isLatest = index === 0;
 57→
 58→      // 버전 + 날짜 헤더
 59→      const versionText = this.add.text(20, currentY, release.version, {
 60→        fontSize: '22px',
 61→        color: '#FFD700',
 62→        fontStyle: 'bold',
 63→        stroke: '#000',
 64→        strokeThickness: 4,
 65→      });
 66→      this.scrollContainer.add(versionText);
 67→
 68→      // NEW 뱃지 (최신 버전만)
 69→      if (isLatest) {
 70→        const badgeCenterX = versionText.x + versionText.width + 32;
 71→        const badgeCenterY = currentY + versionText.height / 2;
 72→        const badgeBg = this.add.rectangle(
 73→          badgeCenterX, badgeCenterY,
 74→          42, 20,
 75→          0xff3333, 1,
 76→        ).setOrigin(0.5, 0.5);
 77→        badgeBg.setStrokeStyle(1, 0xcc0000);
 78→        this.scrollContainer.add(badgeBg);
 79→
 80→        const badgeText = this.add.text(
 81→          badgeCenterX, badgeCenterY,
 82→          'NEW',
 83→          {
 84→            fontSize: '12px',
 85→            color: '#fff',
 86→            fontStyle: 'bold',
 87→          },
 88→        ).setOrigin(0.5, 0.5);
 89→        this.scrollContainer.add(badgeText);
 90→      }
 91→
 92→      const dateText = this.add.text(380, currentY + 5, release.date, {
 93→        fontSize: '15px',
 94→        color: '#ddd',
 95→        fontStyle: 'bold',
 96→        stroke: '#000',
 97→        strokeThickness: 3,
 98→      }).setOrigin(1, 0);
 99→      this.scrollContainer.add(dateText);
100→
101→      currentY += 35;
102→
103→      // 구분선
104→      const line = this.add.rectangle(200, currentY, 360, 2, 0xFFD700, 0.4);
105→      this.scrollContainer.add(line);
106→      currentY += 14;
107→
108→      // 변경사항 목록
109→      release.changes.forEach((change) => {
110→        const changeText = this.add.text(35, currentY, `• ${change}`, {
111→          fontSize: '15px',
112→          color: '#fff',
113→          stroke: '#000',
114→          strokeThickness: 3,
115→          wordWrap: { width: 340 },
116→        });
117→        this.scrollContainer.add(changeText);
118→        currentY += changeText.height + 10;
119→      });
120→
121→      // 릴리즈 간 여백
122→      if (index < RELEASE_NOTES.length - 1) {
123→        currentY += 20;
124→      }
125→    });
126→
127→    // 하단 여백
128→    currentY += 20;
129→
130→    // 스크롤 가능 범위 계산 (컨텐츠 높이 - 보이는 영역 높이)
131→    const visibleHeight = 470;
132→    this.maxScrollY = Math.max(0, currentY - visibleHeight);
133→
134→    // 스크롤 입력 설정
135→    this.setupScrollInput();
136→
137→    // 뒤로가기 버튼 (고정)
138→    this.createBackButton();
139→  }
140→
141→  private setupScrollInput() {
142→    // 터치/마우스 드래그 스크롤
143→    this.input.on('pointerdown', (pointer: Phaser.Input.Pointer) => {
144→      if (pointer.y > 70 && pointer.y < 540) {
145→        this.isDragging = true;
146→        this.dragStartY = pointer.y;
147→        this.dragStartScrollY = this.scrollY;
148→      }
149→    });
150→
151→    this.input.on('pointermove', (pointer: Phaser.Input.Pointer) => {
152→      if (!this.isDragging) return;
153→      const deltaY = this.dragStartY - pointer.y;
154→      this.scrollY = Phaser.Math.Clamp(
155→        this.dragStartScrollY + deltaY,
156→        0,
157→        this.maxScrollY,
158→      );
159→      this.scrollContainer.y = 70 - this.scrollY;
160→    });
161→
162→    this.input.on('pointerup', () => {
163→      this.isDragging = false;
164→    });
165→
166→    // 마우스 휠 스크롤
167→    this.input.on('wheel', (_pointer: Phaser.Input.Pointer, _gameObjects: Phaser.GameObjects.GameObject[], _deltaX: number, deltaY: number) => {
168→      this.scrollY = Phaser.Math.Clamp(
169→        this.scrollY + deltaY * 0.5,
170→        0,
171→        this.maxScrollY,
172→      );
173→      this.scrollContainer.y = 70 - this.scrollY;
174→    });
175→  }
176→
177→  private createBackButton() {
178→    const button = this.add.rectangle(200, 560, 150, 40, 0xffffff, 1).setDepth(10);
179→    button.setStrokeStyle(3, 0x000000);
180→
181→    const text = this.add.text(200, 560, '← 뒤로가기', {
182→      fontSize: '18px',
183→      color: '#000',
184→      fontStyle: 'bold',
185→    }).setOrigin(0.5).setDepth(10);
186→
187→    // 씬 전환 직후 포인터 상태가 남아있어 즉시 pointerdown이 발생하는 것을 방지
188→    this.time.delayedCall(200, () => {
189→      button.setInteractive({ useHandCursor: true });
190→      text.setInteractive({ useHandCursor: true });
191→
192→      [button, text].forEach((element) => {
193→        element.on('pointerover', () => {
194→          button.setFillStyle(0xffff99);
195→        });
196→
197→        element.on('pointerout', () => {
198→          button.setFillStyle(0xffffff);
199→        });
200→
201→        element.on('pointerdown', () => {
202→          this.scene.start('ModeSelectScene');
203→        });
204→      });
205→    });
206→  }
207→}
