  1→import Phaser from 'phaser';
  2→import { GameMode, GAME_MODES, type GameModeConfig } from '../types/GameMode';
  3→import { getSkorBalance, getCachedSkorBalance, cacheSkorBalance } from '../utils/skor';
  4→
  5→export default class ModeSelectScene extends Phaser.Scene {
  6→  private skorText!: Phaser.GameObjects.Text;
  7→
  8→  constructor() {
  9→    super('ModeSelectScene');
 10→  }
 11→
 12→  preload() {
 13→    if (!this.textures.exists('background2')) {
 14→      this.load.image('background2', 'assets/backgrounds/background2.webp');
 15→    }
 16→    if (!this.textures.exists('title')) {
 17→      this.load.image('title', 'assets/title.webp');
 18→    }
 19→  }
 20→
 21→  create() {
 22→    const background = this.add.image(200, 300, 'background2');
 23→    background.setDisplaySize(400, 600);
 24→
 25→    const title = this.add.image(200, 90, 'title');
 26→    title.setScale(0.4);
 27→
 28→    this.add.text(200, 190, '모드를 선택하세요', {
 29→      fontSize: '20px',
 30→      color: '#fff',
 31→      fontStyle: 'bold',
