 89→  private async buildLobby() {
 90→    this.slideshowActive = false;
 91→    this.clearUI();
 92→
 93→    this.slideshowIndex = 0;
 94→    this.slideshowIsA = true;
 95→
 96→    const currentDef = getCharacterDef(SLIDESHOW_IDS[0]);
 97→    const gradeColorInt = parseInt(currentDef.gradeColor.replace('#', ''), 16);
 98→
 99→    // ── 일러스트 배경 2레이어 (crossfade용) ──
100→    // bgA: 처음엔 현재 일러스트 (alpha=1), bgB: 다음 일러스트 대기 (alpha=0)
101→    this.slideshowBgA = this.add.image(200, 300, currentDef.illustKey).setDisplaySize(400, 600);
102→    this.slideshowBgB = this.add.image(200, 300, currentDef.illustKey).setDisplaySize(400, 600).setAlpha(0);
103→
104→    // ── 하단 버튼 영역 그라데이션 ──
105→    const gradSteps = 14;
106→    for (let i = 0; i < gradSteps; i++) {
107→      this.add.rectangle(200, 600 - i * 22, 400, 22, 0x000000, (gradSteps - i) * 0.052);
108→    }
109→
110→    // ── 상단: 배너 배지 (슬라이드마다 등급 색상 업데이트) ──
111→    this.slideshowBadgeBox = this.add.rectangle(200, 36, 140, 30, 0x000000, 0.75)
112→      .setStrokeStyle(1.5, gradeColorInt);
113→    this.slideshowBadgeTxt = this.add.text(200, 36, `✦  ${CURRENT_BANNER.label}  ✦`, {
114→      fontSize: '13px', color: currentDef.gradeColor, fontStyle: 'bold',
115→      stroke: '#000000', strokeThickness: 3,
116→    }).setOrigin(0.5);
117→
118→    // ── 캐릭터 등급 + 이름 — SKOR 잔액(y=408) 바로 위, 겹침 없도록 배치 ──
119→    // grade(13px ≈ 16px high) y=344 → 336~352
120→    // name (28px ≈ 34px high) y=374 → 357~391
121→    // SKOR(15px)              y=408 → 399~417  (gap ≈ 8px)
122→    this.slideshowGradeText = this.add.text(200, 344, currentDef.grade, {
123→      fontSize: '13px', color: currentDef.gradeColor, fontStyle: 'bold',
124→      letterSpacing: 6, stroke: '#000000', strokeThickness: 5,
125→    }).setOrigin(0.5);
126→
127→    this.slideshowNameText = this.add.text(200, 374, currentDef.name, {
128→      fontSize: '28px', color: '#ffffff', fontStyle: 'bold',
129→      stroke: '#000000', strokeThickness: 8,
130→    }).setOrigin(0.5);
131→
132→    // ── SKOR 잔액 ──
133→    const cached = getCachedSkorBalance();
134→    const initialText = cached !== null ? `💰  ${cached} SKOR` : '💰  -- SKOR';
135→    const skorText = this.add.text(200, 408, initialText, {
136→      fontSize: '15px', color: '#aaaaaa',
137→      stroke: '#000000', strokeThickness: 4,
138→    }).setOrigin(0.5);
139→    this.skorBalance = -1;
140→
141→    // ── 뽑기 버튼 ──
142→    this.buildPullButtons(true);
143→
144→    // ── 슬라이드쇼 타이머 (2초마다 자동 전환) ──
145→    this.slideshowActive = true;
146→    this.time.addEvent({
147→      delay: 2000,
148→      loop: true,
149→      callback: this.advanceSlide,
150→      callbackScope: this,
151→    });
152→
153→    // 서버에서 최신 잔액 가져와 갱신
154→    this.skorBalance = await getSkorBalance();
155→    if (!this.scene.isActive()) return;
156→    cacheSkorBalance(this.skorBalance);
157→    skorText.setText(`💰  ${Math.floor(this.skorBalance)} SKOR`);
158→  }
159→
160→  private advanceSlide() {
161→    if (!this.slideshowActive || !this.scene.isActive()) return;
162→
163→    const nextIndex = (this.slideshowIndex + 1) % SLIDESHOW_IDS.length;
164→    const nextDef = getCharacterDef(SLIDESHOW_IDS[nextIndex]);
165→
166→    // 현재/다음 레이어 결정
167→    const current  = this.slideshowIsA ? this.slideshowBgA : this.slideshowBgB;
168→    const incoming = this.slideshowIsA ? this.slideshowBgB : this.slideshowBgA;
169→    if (!current || !incoming) return;
170→
171→    // 다음 일러스트를 incoming 레이어에 세팅
172→    incoming.setTexture(nextDef.illustKey).setAlpha(0);
173→
174→    // 상태 + 텍스트를 일러스트 전환 시작과 동시에 즉시 교체
175→    this.slideshowIsA = !this.slideshowIsA;
176→    this.slideshowIndex = nextIndex;
177→    this.updateSlideshowText(nextDef);
178→
179→    // crossfade: 현재 fade-out, 다음 fade-in
180→    this.tweens.add({ targets: current,  alpha: 0, duration: 600, ease: 'Sine.easeInOut' });
181→    this.tweens.add({ targets: incoming, alpha: 1, duration: 600, ease: 'Sine.easeInOut' });
182→  }
183→
184→  private updateSlideshowText(def: ReturnType<typeof getCharacterDef>) {
185→    const gradeColorInt = parseInt(def.gradeColor.replace('#', ''), 16);
186→
187→    // 배지 색상 즉시 교체
188→    this.slideshowBadgeBox?.setStrokeStyle(1.5, gradeColorInt);
189→    this.slideshowBadgeTxt?.setColor(def.gradeColor);
190→
191→    // 등급·이름: 즉시 텍스트 교체 후 짧게 fade-in (150ms)
192→    if (this.slideshowGradeText?.active) {
193→      this.slideshowGradeText.setText(def.grade).setColor(def.gradeColor).setAlpha(0);
194→      this.tweens.add({ targets: this.slideshowGradeText, alpha: 1, duration: 150 });
195→    }
196→    if (this.slideshowNameText?.active) {
197→      this.slideshowNameText.setText(def.name).setAlpha(0);
198→      this.tweens.add({ targets: this.slideshowNameText, alpha: 1, duration: 150 });
199→    }
200→  }

