 292→  private buildCharacterGrid() {
 293→    this.cardHighlights.clear();
 294→    this.coresGfx = this.add.graphics();
 295→    CHARACTERS.forEach((char, index) => {
 296→      const col = index % COLS;
 297→      const row = Math.floor(index / COLS);
 298→      const x = GRID_LEFT + col * (CARD_W + GAP_X) + CARD_W / 2;
 299→      const y = GRID_TOP + row * (CARD_H + GAP_Y) + CARD_H / 2;
 300→      this.createCharacterCard(char, x, y);
 301→    });
 302→    this.cardsContainer.add(this.coresGfx);
 303→
 304→    const totalRows = Math.ceil(CHARACTERS.length / COLS);
 305→    const contentBottom = GRID_TOP + (totalRows - 1) * (CARD_H + GAP_Y) + CARD_H + 10;
 306→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
 307→  }
 308→
 309→  private buildWallpaperGrid() {
 310→    this.wpHighlights.clear();
 311→    // ownedWpIds: create() 초기화 + sync callback에서 직접 갱신
 312→    // selectedWpId: applyWallpaper()가 항상 동기 업데이트 → 재조회 불필요
 313→
 314→    const availableWps = WALLPAPERS.filter(w => AVAILABLE_WP_SET.has(w.id));
 315→    availableWps.forEach((wp, index) => {
 316→      const col = index % WP_COLS;
 317→      const row = Math.floor(index / WP_COLS);
 318→      const x = WP_GRID_LEFT + col * (WP_CARD_W + WP_GAP_X) + WP_CARD_W / 2;
 319→      const y = WP_GRID_TOP + row * (WP_CARD_H + WP_GAP_Y) + WP_CARD_H / 2;
 320→      this.createWallpaperCard(wp, x, y);
 321→    });
 322→
 323→    const totalRows = Math.ceil(availableWps.length / WP_COLS);
 324→    const contentBottom = WP_GRID_TOP + (totalRows - 1) * (WP_CARD_H + WP_GAP_Y) + WP_CARD_H + 10;
 325→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
 326→  }
