 595→  private createCharacterCard(char: CharacterDef, x: number, y: number) {
 596→    const isOwned = this.ownedIds.includes(char.id);
 597→    const isSelected = this.selectedId === char.id;
 598→    const gradeColorInt = parseInt(char.gradeColor.replace('#', ''), 16);
 599→
 600→    // 카드 배경
 601→    const cardBg = this.add.rectangle(x, y, CARD_W, CARD_H, 0x222222);
 602→    cardBg.setStrokeStyle(2, isOwned ? gradeColorInt : 0x444444);
 603→    this.cardsContainer.add(cardBg);
 604→
 605→    // 선택 하이라이트
 606→    const highlight = this.add.rectangle(x, y, CARD_W, CARD_H, 0, 0);
 607→    highlight.setStrokeStyle(3, 0xffffff);
 608→    highlight.setVisible(isSelected);
 609→    this.cardHighlights.set(char.id, highlight);
 610→    this.cardsContainer.add(highlight);
 611→
 612→    // 캐릭터 이미지
 613→    const img = this.add.image(x, y - 12, char.imageKey);
 614→    img.setDisplaySize(58, 85);
 615→    this.cardsContainer.add(img);
 616→
 617→    if (!isOwned) {
 618→      img.setTint(0x000000);
 619→      img.setAlpha(0.6);
 620→      const lock = this.add.text(x, y - 12, '🔒', { fontSize: '22px' }).setOrigin(0.5);
 621→      this.cardsContainer.add(lock);
 622→    }
 623→
 624→    // 등급 배지
 625→    const badge = this.add.text(x + CARD_W / 2 - 2, y - CARD_H / 2 + 2, char.grade, {
 626→      fontSize: '9px',
 627→      color: char.gradeColor,
 628→      fontStyle: 'bold',
 629→      backgroundColor: '#000000cc',
 630→      padding: { x: 3, y: 1 },
 631→    }).setOrigin(1, 0);
 632→    this.cardsContainer.add(badge);
 633→
 634→    // 각성 코어 (등급외 제외, 보유 캐릭터만) — 공유 coresGfx에 직접 그림
 635→    if (isOwned && char.grade !== '등급외') {
 636→      const dupCount   = getDuplicateCount(char.id);
 637→      const awakeLevel = getAwakeningLevel(char.grade, dupCount);
 638→      const coreY      = y + CARD_H / 2 - CORE_Y_OFFSET;
 639→
 640→      for (let i = 0; i < CORE_COUNT; i++) {
 641→        const cx = x + (i - 2) * CORE_GAP;
 642→        if (i < awakeLevel) {
 643→          // 충전된 코어: 외곽 글로우 + 내부 밝은 원
 644→          this.coresGfx.fillStyle(gradeColorInt, 0.25);
 645→          this.coresGfx.fillCircle(cx, coreY, CORE_GLOW_RADIUS);
 646→          this.coresGfx.fillStyle(gradeColorInt, 1);
 647→          this.coresGfx.fillCircle(cx, coreY, CORE_INNER_RADIUS);
 648→          this.coresGfx.fillStyle(0xffffff, 0.55);
 649→          this.coresGfx.fillCircle(cx - 1, coreY - 1, CORE_HIGHLIGHT_R);
 650→        } else {
 651→          // 빈 코어: 어두운 원 + 얇은 테두리
 652→          this.coresGfx.fillStyle(0x111111, 1);
 653→          this.coresGfx.fillCircle(cx, coreY, CORE_INNER_RADIUS);
 654→          this.coresGfx.lineStyle(1, gradeColorInt, 0.35);
 655→          this.coresGfx.strokeCircle(cx, coreY, CORE_INNER_RADIUS);
 656→        }
 657→      }
 658→    }
 659→
 660→    // 캐릭터 이름
 661→    const nameText = this.add.text(x, y + CARD_H / 2 - 16, char.name, {
 662→      fontSize: '12px',
 663→      color: isOwned ? '#ffffff' : '#555555',
 664→      fontStyle: 'bold',
 665→    }).setOrigin(0.5);
 666→    this.cardsContainer.add(nameText);
 667→
 668→    // 모든 카드 클릭 가능 (탭 → 상세 패널 열기)
 669→    cardBg.setInteractive({ useHandCursor: isOwned });
 670→
 671→    if (isOwned) {
 672→      cardBg.on('pointerover', () => {
 673→        if (this.selectedId !== char.id) cardBg.setFillStyle(0x333333);
 674→      });
 675→      cardBg.on('pointerout', () => {
 676→        if (this.selectedId !== char.id) cardBg.setFillStyle(0x222222);
 677→      });
 678→    }
 679→    // pointerup으로 상세 패널 열기 (드래그 스크롤과 구분, 이전 씬 bleed-through 방지)
 680→    cardBg.on('pointerup', () => {
 681→      if (!this.hasDragged && this.hasPointerDownInScene) this.showCharacterDetail(char.id);
 682→    });
 683→  }
