 64→  private createDifficultyButtons() {
 65→    this.difficultyButtons.forEach(btn => btn.destroy());
 66→    this.difficultyButtons.clear();
 67→
 68→    const difficulties: Difficulty[] = [
 69→      DifficultyEnum.NORMAL,
